function RichEditor({editorRef,required=false}:{editorRef:any;required?:boolean}){
 const run=(command:string,value?:string)=>{editorRef.current?.focus();document.execCommand(command,false,value);};
 const button=(label:string,command:string,value?:string)=><button type="button" title={label} aria-label={label} onMouseDown={e=>e.preventDefault()} onClick={()=>run(command,value)}>{label}</button>;
 return <div className="word-editor">
  <div className="word-toolbar" role="toolbar" aria-label="Detailed explanation formatting">
   <select aria-label="Font family" defaultValue="Arial" onChange={e=>run('fontName',e.target.value)}><option>Arial</option><option>Calibri</option><option>Georgia</option><option>Tahoma</option><option>Verdana</option></select>
   <select aria-label="Font size" defaultValue="" onChange={e=>{if(e.target.value)run('fontSize',e.target.value);e.target.value=''}}><option value="" disabled>Size</option><option value="2">10</option><option value="3">12</option><option value="4">14</option><option value="5">18</option><option value="6">24</option></select>
   <span className="word-toolbar-divider"/>
   {button('Bold','bold')} {button('Italic','italic')} {button('Underline','underline')} {button('Strikethrough','strikeThrough')}
   <span className="word-toolbar-divider"/>
   {button('Bulleted list','insertUnorderedList','')}{button('Numbered list','insertOrderedList','')}
   {button('Align left','justifyLeft','')}{button('Align center','justifyCenter','')}{button('Align right','justifyRight','')}
   <span className="word-toolbar-divider"/>
   {button('Undo','undo','')}{button('Redo','redo','')}
   <label className="word-color" title="Text color">A<input type="color" aria-label="Text color" defaultValue="#17283e" onChange={e=>run('foreColor',e.target.value)}/></label>
   <label className="word-color word-highlight" title="Highlight color">▰<input type="color" aria-label="Highlight color" defaultValue="#fff2a8" onChange={e=>run('hiliteColor',e.target.value)}/></label>
   {button('Clear formatting','removeFormat','')}
  </div>
  <div ref={editorRef} className="word-editable" contentEditable role="textbox" aria-label="Detailed Explanation" aria-multiline="true" aria-required={required} data-placeholder={required?'Describe the item and its identifying details…':'Type a detailed explanation…'} onInput={()=>{}}/>
 </div>;
}
